// Regenerates src/market/normal-table.ts from the independent oracle. Run: bun run normal-table:update
import { writeFileSync } from "node:fs"
import { oracleHalfTable, roundToMillionths } from "../src/golden/oracle-normal"

const SIZES = [16, 32, 64, 128, 256, 512, 1024]
const lines = SIZES.map((buckets) => {
	const half = oracleHalfTable(buckets).map((value) => roundToMillionths(value).toString())
	return `\t${buckets}: "${half.join(",")}",`
})
const text = `/**
 * GENERATED by scripts/normal-table-update.ts from src/golden/oracle-normal.ts; do not edit by hand.
 * Each entry is the upper half of the standard normal quantiles at the midpoints of \`buckets\`
 * equal-probability intervals, ascending, as integers in millionths. The lower half is the mirror.
 * The long lines are data: one comma-separated string per bucket count keeps the file short.
 */
export const NORMAL_HALF_TABLES: Readonly<Record<number, string>> = {
${lines.join("\n")}
}
`
writeFileSync(new URL("../src/market/normal-table.ts", import.meta.url), text)
